#include "cs2_radar.hpp"
#include "cs2/simulator.hpp"
#include <cstdio>
namespace { void verdict(const t4_cs2::BlueSensorReport& r) { std::printf("sensors: handle_graph=%d cooccurrence=%d handle_race=%d overlay=%d module_integrity=%d kernel_driver=%d device_watch=%d callback_tamper=%d trust_policy=%d hv_probe=%d bridge_intel=%d attestation=%d dma_device=%d iommu_off=%d capture_desktop_clone=%d lag_switch_info_advantage=%d\n", r.handle_graph, r.cooccurrence, r.handle_race, r.overlay, r.module_integrity, r.kernel_driver, r.device_watch, r.callback_tamper, r.trust_policy, r.hv_probe, r.bridge_intel, r.attestation, r.dma_device, r.iommu_off, r.structural_fog, r.info_advantage); for (const auto& reason : r.reasons) std::printf("  - %s\n", reason.c_str()); std::printf("risk=%.2f signals=%d\n", r.risk, r.signal_count); } }
int main() { auto arena = ::cs2::make_cs2_arena(); std::printf("T4 red capability catalog:\n"); for (const auto& c : t4_cs2::list_red_capabilities()) std::printf("  %s: %s\n", c.name, c.description); t4_cs2::Cs2Radar radar(arena.world); if (!radar.enable_dma() || !radar.scan_entities()) return 1; radar.render_radar_console(true); const auto report = radar.adaptive_red_loop(); std::printf("T4 adaptive verdict: survived=%d detected=%d\n", report.survived, report.detected_count); verdict(radar.blue_multi_sensor_scan()); return 0; }
